package com.yuegang.zhihui.knowledge.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.knowledge.application.*;import com.yuegang.zhihui.knowledge.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/knowledge/documents/{id}/metadata")public final class KnowledgeMetadataController{private final KnowledgeMetadataService service;private final KnowledgeUserResolver users;public KnowledgeMetadataController(KnowledgeMetadataService s,KnowledgeUserResolver u){service=s;users=u;}@GetMapping ApiResponse<KnowledgeMetadataView>get(@PathVariable String id,HttpServletRequest r){users.resolve(r,false);return ok(service.view(Long.parseLong(id)),r);}@PutMapping ApiResponse<KnowledgeMetadataView>update(@PathVariable String id,@Valid @RequestBody UpdateKnowledgeMetadataRequest b,HttpServletRequest r){return ok(service.update(users.resolve(r,true),id,b),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
